          .withZone(ZoneId.systemDefault());
  public static void main(String[] a) throws Exception {
    long now = System.currentTimeMillis();
    SimpleDateFormat sdf = new SimpleDateFormat("EEE MMM dd HH:mm:ss Z yyyy", Locale.US);
