840	    synchronized void loadDetailLog(TimelineDataManager tdm,
841	        TimelineEntityGroupId groupId) throws IOException {
842	      List<LogInfo> removeList = new ArrayList<>();
843	      for (LogInfo log : detailLogs) {
844	        LOG.debug("Try refresh logs for {}", log.getFilename());
845	        // Only refresh the log that matches the cache id
846	        if (log.matchesGroupId(groupId)) {
847	          Path dirPath = getAppDirPath();
848	          if (fs.exists(log.getPath(dirPath))) {
849	            LOG.debug("Refresh logs for cache id {}", groupId);
850	            log.parseForStore(tdm, dirPath, isDone(),
851	                jsonFactory, objMapper, fs);
852	          } else {
853	            // The log may have been removed, remove the log
854	            removeList.add(log);
855	            LOG.info(
856	                "File {} no longer exists, removing it from log list",
857	                log.getPath(dirPath));
858	          }
859	        }
860	      }
861	      detailLogs.removeAll(removeList);
862	    }
