864	    public synchronized void moveToDone() throws IOException {
865	      Path doneAppPath = getDoneAppPath(appId);
866	      if (!doneAppPath.equals(appDirPath)) {
867	        Path donePathParent = doneAppPath.getParent();
868	        if (!fs.exists(donePathParent)) {
869	          fs.mkdirs(donePathParent);
870	        }
871	        LOG.debug("Application {} is done, trying to move to done dir {}",
872	            appId, doneAppPath);
873	        if (!fs.rename(appDirPath, doneAppPath)) {
874	          throw new IOException("Rename " + appDirPath + " to " + doneAppPath
875	              + " failed");
876	        } else {
877	          LOG.info("Moved {} to {}", appDirPath, doneAppPath);
878	        }
879	        appDirPath = doneAppPath;
880	      }
881	    }
882	  }
