885	   * Extract any nested throwable forwarded from IPC operations.
886	   * @param e exception
887	   * @return either the exception passed an an argument, or any nested
888	   * exception which was wrapped inside an {@link UndeclaredThrowableException}
889	   */
890	  private Throwable extract(Exception e) {
891	    Throwable t = e;
892	    if (e instanceof UndeclaredThrowableException && e.getCause() != null) {
893	      t = e.getCause();
894	    }
895	    return t;
896	  }
