87	  @InterfaceAudience.Private
88	  @VisibleForTesting
89	  boolean matchesGroupId(String groupId){
90	    // Return true if the group id is a segment (separated by _, ., or end of
91	    // string) of the file name.
92	    int pos = filename.indexOf(groupId);
93	    if (pos < 0) {
94	      return false;
95	    }
96	    return filename.length() == pos + groupId.length()
97	        || ENTITY_FILE_NAME_DELIMITERS.contains(String.valueOf(
98	        filename.charAt(pos + groupId.length())
99	    ));
100	  }
