102	  public long parseForStore(TimelineDataManager tdm, Path appDirPath,
103	      boolean appCompleted, JsonFactory jsonFactory, ObjectMapper objMapper,
104	      FileSystem fs) throws IOException {
105	    LOG.debug("Parsing for log dir {} on attempt {}", appDirPath,
106	        attemptDirName);
107	    Path logPath = getPath(appDirPath);
108	    FileStatus status = fs.getFileStatus(logPath);
109	    long numParsed = 0;
110	    if (status != null) {
111	      long startTime = Time.monotonicNow();
112	      try {
113	        LOG.debug("Parsing {} at offset {}", logPath, offset);
114	        long count = parsePath(tdm, logPath, appCompleted, jsonFactory,
115	            objMapper, fs);
116	        LOG.info("Parsed {} entities from {} in {} msec",
117	            count, logPath, Time.monotonicNow() - startTime);
118	        numParsed += count;
119	      } catch (RuntimeException e) {
120	        // If AppLogs cannot parse this log, it may be corrupted or just empty
121	        if (e.getCause() instanceof JsonParseException &&
122	            (status.getLen() > 0 || offset > 0)) {
123	          // log on parse problems if the file as been read in the past or
124	          // is visibly non-empty
125	          LOG.info("Log {} appears to be corrupted. Skip. ", logPath);
126	        }
127	      }
128	    } else {
129	      LOG.warn("{} no longer exists. Skip for scanning. ", logPath);
130	    }
131	    return numParsed;
132	  }
133	
134	  private long parsePath(TimelineDataManager tdm, Path logPath,
135	      boolean appCompleted, JsonFactory jsonFactory, ObjectMapper objMapper,
136	      FileSystem fs) throws IOException {
137	    UserGroupInformation ugi =
138	        UserGroupInformation.createRemoteUser(user);
139	    FSDataInputStream in = fs.open(logPath);
140	    JsonParser parser = null;
141	    try {
142	      in.seek(offset);
143	      try {
144	        parser = jsonFactory.createParser((InputStream)in);
145	        parser.configure(JsonParser.Feature.AUTO_CLOSE_SOURCE, false);
146	      } catch (IOException e) {
147	        // if app hasn't completed then there may be errors due to the
148	        // incomplete file which are treated as EOF until app completes
149	        if (appCompleted) {
150	          throw e;
151	        } else {
152	          LOG.debug("Exception in parse path: {}", e.getMessage());
153	          return 0;
154	        }
155	      }
156	
157	      return doParse(tdm, parser, objMapper, ugi, appCompleted);
158	    } finally {
159	      IOUtils.closeStream(parser);
160	      IOUtils.closeStream(in);
161	    }
162	  }
163	
164	  protected abstract long doParse(TimelineDataManager tdm, JsonParser parser,
165	      ObjectMapper objMapper, UserGroupInformation ugi, boolean appCompleted)
166	      throws IOException;
167	}
