169	class EntityLogInfo extends LogInfo {
170	  private static final Logger LOG = LoggerFactory.getLogger(
171	      EntityGroupFSTimelineStore.class);
172	
173	  public EntityLogInfo(String attemptId,
174	      String file, String owner) {
175	    super(attemptId, file, owner);
176	  }
177	
178	  @Override
179	  protected long doParse(TimelineDataManager tdm, JsonParser parser,
180	      ObjectMapper objMapper, UserGroupInformation ugi, boolean appCompleted)
181	      throws IOException {
182	    long count = 0;
183	    TimelineEntities entities = new TimelineEntities();
184	    ArrayList<TimelineEntity> entityList = new ArrayList<TimelineEntity>(1);
185	    long bytesParsed;
186	    long bytesParsedLastBatch = 0;
187	    boolean postError = false;
188	    try {
189	      MappingIterator<TimelineEntity> iter = objMapper.readValues(parser,
190	          TimelineEntity.class);
191	
192	      while (iter.hasNext()) {
193	        TimelineEntity entity = iter.next();
